mapper.update:
update biz_chat_session_user
set unread_count = 0,
    last_read_message_id = #{messageId},
    update_time = sysdate()
where session_id = #{sessionId}
  and user_id = #{userId}

update biz_chat_session_user
set unread_count = coalesce(unread_count, 0) + 1,
    update_time = sysdate()
where session_id = #{sessionId}
  and user_id != #{senderId}
